// Edit this to match your actual rate.
const RATE_PER_HOUR = 350; // PHP, per court, per hour
const LONG_TERM_NOTE = "Long-term booking"; // marks entries that render red (vs orange for one-off)

// Weekday promo: Mon–Fri, every 4th hour in a booking is free (repeats for longer bookings —
// e.g. 8 hours = 2 free hours). Set PROMO_REPEATS to false to cap it at one free hour max.
// Only applies to morning sessions (before 12 noon) — courts open at 8AM, so in practice
// this covers the 8–11AM block. If the selected hours run past noon, no discount applies.
const PROMO_FREE_EVERY_N_HOURS = 4;
const PROMO_REPEATS = true;
const PROMO_MORNING_CUTOFF_HOUR = 12; // hours must all be < this to qualify
function isPromoWeekday(dateObj) {
  const wd = dateObj.getDay(); // 0=Sun ... 6=Sat
  return wd >= 1 && wd <= 5;
}
function isMorningSession(sortedHrs) {
  return sortedHrs.length > 0 && sortedHrs.every((h) => h < PROMO_MORNING_CUTOFF_HOUR);
}
function getFreeHourSet(dateObj, sortedHrs) {
  const free = new Set();
  if (!isPromoWeekday(dateObj)) return free;
  if (!isMorningSession(sortedHrs)) return free;
  sortedHrs.forEach((h, idx) => {
    const position = idx + 1; // 1-based
    if (position % PROMO_FREE_EVERY_N_HOURS === 0) {
      if (PROMO_REPEATS || free.size === 0) free.add(h);
    }
  });
  return free;
}

function hoursToRangeLabel(hrs) {
  if (!hrs.length) return "";
  const sorted = [...hrs].sort((a, b) => a - b);
  const ranges = [];
  let start = sorted[0];
  let prev = sorted[0];
  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i] === prev + 1) {
      prev = sorted[i];
      continue;
    }
    ranges.push([start, prev]);
    start = sorted[i];
    prev = sorted[i];
  }
  ranges.push([start, prev]);
  return ranges.map(([s, e]) => (s === e ? fmtHour(s) : `${fmtHour(s)} – ${fmtHour(e + 1)}`)).join(", ");
}

function courtsForSelection(sel) {
  return sel === "both" ? ["1", "2"] : [sel];
}

function courtLabel(sel) {
  if (sel === "both") return "Both Courts";
  return `Court ${sel}`;
}

